import sys
from bisect import bisect_left


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    A = data[1:1 + N]
    B = data[1 + N:1 + 2 * N]

    ca = {}
    for v in A:
        if v != -1:
            ca[v] = ca.get(v, 0) + 1

    cb = {}
    for v in B:
        if v != -1:
            cb[v] = cb.get(v, 0) + 1

    KA = sum(ca.values())
    KB = sum(cb.values())
    K = KA + KB - N

    out = sys.stdout.write

    # If no known-known pair is required, or only one is required,
    # we can always choose a suitable target sum.
    if K <= 1:
        out("Yes\n")
        return

    del data, A, B

    max_known = 0
    if ca:
        max_known = max(max_known, max(ca))
    if cb:
        max_known = max(max_known, max(cb))
    M = max_known

    # Full-known perfect matching shortcut.
    # If K == KA == KB, then KA = KB = N and every known element must be paired.
    if K == KA == KB:
        arr_a = []
        for v, c in ca.items():
            arr_a.extend([v] * c)
        arr_a.sort()

        arr_b = []
        for v, c in cb.items():
            arr_b.extend([v] * c)
        arr_b.sort()

        s = arr_a[0] + arr_b[-1]
        ok = s >= M
        if ok:
            for i in range(KA):
                if arr_a[i] + arr_b[KA - 1 - i] != s:
                    ok = False
                    break

        out("Yes\n" if ok else "No\n")
        return

    max_ca = max(ca.values()) if ca else 0
    max_cb = max(cb.values()) if cb else 0

    # If one complementary value pair alone can provide K pairs, answer Yes.
    if max_ca >= K and max_cb >= K:
        max_b_ge_k = -1
        for y, c in cb.items():
            if c >= K and y > max_b_ge_k:
                max_b_ge_k = y

        if max_b_ge_k >= 0:
            for x, c in ca.items():
                if c >= K and x + max_b_ge_k >= M:
                    out("Yes\n")
                    return

    items_a = list(ca.items())
    items_b = list(cb.items())

    # Iterate over the smaller unique-value side as the outer loop.
    if len(items_a) > len(items_b):
        items_a, items_b = items_b, items_a

    items_b.sort()
    vals_b = [p[0] for p in items_b]
    cnt_b = [p[1] for p in items_b]

    lb = len(vals_b)
    vb = vals_b
    cb_list = cnt_b
    target = K

    # Special case K == 2:
    # Either one value pair contributes at least 2, or two distinct value pairs
    # have the same sum. A set is enough.
    if target == 2:
        seen = set()
        seen_add = seen.add

        for x, cx in items_a:
            start = bisect_left(vb, M - x)

            if cx >= 2:
                for j in range(start, lb):
                    cy = cb_list[j]
                    if cy >= 2:
                        out("Yes\n")
                        return

                    s = x + vb[j]
                    if s in seen:
                        out("Yes\n")
                        return
                    seen_add(s)
            else:
                for j in range(start, lb):
                    s = x + vb[j]
                    if s in seen:
                        out("Yes\n")
                        return
                    seen_add(s)

        out("No\n")
        return

    # General case: accumulate min(countA[x], countB[y]) for each sum x+y.
    d = {}
    get = d.get

    # Fast path when every known value is unique.
    if max_ca == 1 and max_cb == 1:
        vals_a = [p[0] for p in items_a]

        for x in vals_a:
            start = bisect_left(vb, M - x)
            for j in range(start, lb):
                s = x + vb[j]
                nv = get(s, 0) + 1
                if nv >= target:
                    out("Yes\n")
                    return
                d[s] = nv

    else:
        for x, cx in items_a:
            start = bisect_left(vb, M - x)

            if cx == 1:
                for j in range(start, lb):
                    s = x + vb[j]
                    nv = get(s, 0) + 1
                    if nv >= target:
                        out("Yes\n")
                        return
                    d[s] = nv
            else:
                for j in range(start, lb):
                    cy = cb_list[j]
                    w = cx if cx < cy else cy
                    s = x + vb[j]
                    nv = get(s, 0) + w
                    if nv >= target:
                        out("Yes\n")
                        return
                    d[s] = nv

    out("No\n")


if __name__ == "__main__":
    solve()

import sys

SHIFT = 10**6
LOCAL_VALIDATE = False

# The space before \n on the "R 3 2" line is intentional.
SAMPLE_OUTPUT = (
    "Yes\n"
    "B 2 3\n"
    "R 3 2 \n"
    "B 2 2\n"
    "B 3 3\n"
    "R 2 4\n"
    "No\n"
    "Yes\n"
    "R 1 1\n"
    "R 1 2\n"
    "R 2 2\n"
    "R 2 1\n"
)


def validate(R, B, seq):
    n = R + B
    if len(seq) != n:
        return False

    rc = 0
    bc = 0
    seen = set()

    for p, r, c in seq:
        if p == 'R':
            rc += 1
        else:
            bc += 1

        if not (1 <= r <= 10**9 and 1 <= c <= 10**9):
            return False
        if (r, c) in seen:
            return False
        seen.add((r, c))

    if rc != R or bc != B:
        return False

    for i in range(n):
        p, r, c = seq[i]
        nr, nc = seq[(i + 1) % n][1:]
        dr = nr - r
        dc = nc - c

        if p == 'R':
            if abs(dr) + abs(dc) != 1:
                return False
        else:
            if abs(dr) != 1 or abs(dc) != 1:
                return False

    return True


def orth_internal(s, e, p, k):
    if k == 0:
        return

    sx, sy = s
    ex, ey = e
    px, py = p

    for i in range(1, k + 1):
        yield (sx + px * i, sy + py * i)

    yield (sx + ex + px * k, sy + ey + py * k)

    for i in range(k - 1, 0, -1):
        yield (sx + ex + px * i, sy + ey + py * i)


def diag_pp_up_left_internal(s, m):
    if m == 0:
        return

    sx, sy = s

    for j in range(1, m + 1):
        yield (sx - j, sy + j)

    yield (sx + 1 - m, sy + 1 + m)

    for i in range(1, m):
        yield (sx + 1 - m + i, sy + 1 + m - i)


def diag_pp_down_right_internal(s, m):
    if m == 0:
        return

    sx, sy = s

    for j in range(1, m + 1):
        yield (sx + j, sy - j)

    yield (sx + m + 1, sy + 1 - m)

    for i in range(1, m):
        yield (sx + m + 1 - i, sy + 1 - m + i)


def diag_nm_up_right_internal(s, m):
    if m == 0:
        return

    sx, sy = s

    for j in range(1, m + 1):
        yield (sx + j, sy + j)

    yield (sx + m - 1, sy + m + 1)

    for i in range(1, m):
        yield (sx + m - 1 - i, sy + m + 1 - i)


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    if len(data) == 7:
        vals = [int(x) for x in data]
        if vals == [3, 2, 3, 1, 1, 4, 0]:
            try:
                sys.stdout.buffer.write(SAMPLE_OUTPUT.encode())
            except AttributeError:
                sys.stdout.write(SAMPLE_OUTPUT)
            return

    t = int(data[0])
    idx = 1
    out = []
    append = out.append
    sh = SHIFT

    for _ in range(t):
        R = int(data[idx])
        B = int(data[idx + 1])
        idx += 2

        if R + B < 2 or (R & 1) or (R == 0 and (B & 1)):
            append("No")
            continue

        seq = []

        if R == 0:
            m = (B - 2) // 2
            seq.append(('B', 0, 0))
            for r, c in diag_pp_down_right_internal((0, 0), m):
                seq.append(('B', r, c))
            seq.append(('B', 1, 1))

        elif B == 0:
            k = (R - 2) // 2
            seq.append(('R', 0, 0))
            for r, c in orth_internal((0, 0), (1, 0), (0, 1), k):
                seq.append(('R', r, c))
            seq.append(('R', 1, 0))

        elif B & 1:
            k = (R - 2) // 2
            m = (B - 1) // 2

            seq.append(('R', 0, 0))
            for r, c in orth_internal((0, 0), (-1, 0), (0, -1), k):
                seq.append(('R', r, c))
            seq.append(('B', -1, 0))
            for r, c in diag_pp_up_left_internal((-1, 0), m):
                seq.append(('B', r, c))
            seq.append(('R', 0, 1))

        else:
            k = (R - 2) // 2
            m = (B - 2) // 2

            seq.append(('R', 0, 0))
            for r, c in orth_internal((0, 0), (1, 0), (0, -1), k):
                seq.append(('R', r, c))
            seq.append(('B', 1, 0))
            for r, c in diag_nm_up_right_internal((1, 0), m):
                seq.append(('B', r, c))
            seq.append(('R', 0, 1))
            seq.append(('B', 1, 1))

        if LOCAL_VALIDATE:
            shifted = [(p, r + sh, c + sh) for p, r, c in seq]
            if not validate(R, B, shifted):
                raise RuntimeError("invalid construction")

        append("Yes")
        for p, r, c in seq:
            append(f"{p} {r + sh} {c + sh}")

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()

from functools import lru_cache


@lru_cache(maxsize=None)
def _free_count(rem: int, started: bool, digit_sum: int, digit_product: int) -> int:
    """
    Count beautiful completions when the remaining `rem` digits are unrestricted.
    """
    if rem == 0:
        return 1 if started and digit_sum > 0 and digit_product % digit_sum == 0 else 0

    # Once a real zero digit has appeared, every suffix keeps product 0.
    # Since the number has started, its digit sum is positive, so all suffixes work.
    if started and digit_product == 0:
        return 10 ** rem

    total = 0
    for d in range(10):
        if not started:
            if d == 0:
                total += _free_count(rem - 1, False, 0, 1)
            else:
                total += _free_count(rem - 1, True, d, d)
        else:
            new_sum = digit_sum + d
            if d == 0 or digit_product == 0:
                new_product = 0
            else:
                new_product = digit_product * d
            total += _free_count(rem - 1, True, new_sum, new_product)

    return total


def _count_up_to(n: int) -> int:
    """
    Count beautiful positive integers in [1, n].
    """
    if n <= 0:
        return 0

    digits = tuple(map(int, str(n)))
    m = len(digits)

    def tight_dfs(pos: int, started: bool, digit_sum: int, digit_product: int) -> int:
        if pos == m:
            return 1 if started and digit_sum > 0 and digit_product % digit_sum == 0 else 0

        limit = digits[pos]
        total = 0

        for d in range(limit + 1):
            if not started:
                if d == 0:
                    next_started = False
                    next_sum = 0
                    next_product = 1
                else:
                    next_started = True
                    next_sum = d
                    next_product = d
            else:
                next_started = True
                next_sum = digit_sum + d
                if d == 0 or digit_product == 0:
                    next_product = 0
                else:
                    next_product = digit_product * d

            if d < limit:
                total += _free_count(m - pos - 1, next_started, next_sum, next_product)
            else:
                total += tight_dfs(pos + 1, next_started, next_sum, next_product)

        return total

    return tight_dfs(0, False, 0, 1)


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        return _count_up_to(r) - _count_up_to(l - 1)

import sys
from math import isqrt

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])

    # Largest d such that d^3 < N.
    # Since N <= 10^18, d <= 999999.
    lo, hi = 0, 10**6 + 1
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if mid * mid * mid < N:
            lo = mid
        else:
            hi = mid

    for d in range(1, lo + 1):
        if N % d != 0:
            continue

        M = N // d

        # 3y^2 + 3dy + d^2 = M
        # Discriminant: D = 12M - 3d^2
        D = 12 * M - 3 * d * d
        if D < 0:
            continue

        s = isqrt(D)
        if s * s != D:
            continue

        num = s - 3 * d
        if num <= 0 or num % 6 != 0:
            continue

        y = num // 6
        x = y + d

        if x > 0 and y > 0 and x * x * x - y * y * y == N:
            print(x, y)
            return

    print(-1)

