import sys
from collections import deque

sys.setrecursionlimit(1000000)


class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]
        self.level = []
        self.it = []

    def add_edge(self, fr, to, cap):
        if fr == to:
            return
        self.g[fr].append([to, len(self.g[to]), cap])
        self.g[to].append([fr, len(self.g[fr]) - 1, 0])

    def bfs(self, s, t):
        level = [-1] * self.n
        level[s] = 0
        q = deque([s])
        g = self.g
        while q:
            v = q.popleft()
            for e in g[v]:
                if e[2] > 0 and level[e[0]] < 0:
                    level[e[0]] = level[v] + 1
                    q.append(e[0])
        self.level = level
        return level[t] >= 0

    def dfs(self, v, t, f):
        if v == t:
            return f
        g = self.g
        level = self.level
        it = self.it
        while it[v] < len(g[v]):
            e = g[v][it[v]]
            if e[2] > 0 and level[e[0]] == level[v] + 1:
                d = self.dfs(e[0], t, min(f, e[2]))
                if d:
                    e[2] -= d
                    g[e[0]][e[1]][2] += d
                    return d
            it[v] += 1
        return 0

    def max_flow(self, s, t, limit=10**18):
        flow = 0
        while flow < limit and self.bfs(s, t):
            self.it = [0] * self.n
            while flow < limit:
                f = self.dfs(s, t, limit - flow)
                if f == 0:
                    break
                flow += f
        return flow


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    K = int(next(it))

    edges = []
    for _ in range(M):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        edges.append((u, v))

    maxD = min(K, N - 1)
    INF = 10**9

    def feasible(D):
        if D == 0:
            return True

        total = N * D
        s = total
        t = total + 1
        dinic = Dinic(total + 2)

        def node(v, i):
            return v * D + i

        # Force d_1 = 0 and d_N = D.
        for v in range(N):
            for i in range(D):
                nid = node(v, i)
                if v == 0:
                    dinic.add_edge(nid, t, INF)
                if v == N - 1:
                    dinic.add_edge(s, nid, INF)

        # Monotonicity: x_{v,i+1} => x_{v,i}.
        for v in range(N):
            for i in range(D - 1):
                dinic.add_edge(node(v, i + 1), node(v, i), INF)

        # Transition constraints and costs.
        for u, v in edges:
            # x_{v,i+1} => x_{u,i}, enforcing d_v <= d_u + 1.
            for i in range(D - 1):
                dinic.add_edge(node(v, i + 1), node(u, i), INF)

            # Cost 1 when x_{v,i} is true and x_{u,i} is false.
            for i in range(D):
                dinic.add_edge(node(v, i), node(u, i), 1)

        return dinic.max_flow(s, t, K + 1) <= K

    lo, hi = 0, maxD + 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid

    print(lo)


if __name__ == "__main__":
    solve()

import sys

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    X = int(data[1])
    Y = int(data[2])
    S = data[3]
    T = data[4]

    # Invariant sequences for S:
    #   positions of '1' modulo X, in order
    #   positions of '0' modulo Y, in order
    ones = []
    zeros = []

    for i, ch in enumerate(S):
        if ch == 49:  # ord('1')
            ones.append(i % X)
        else:
            zeros.append(i % Y)

    oi = 0
    zi = 0
    len_ones = len(ones)
    len_zeros = len(zeros)

    # Stream T and compare against S's invariant sequences.
    for i, ch in enumerate(T):
        if ch == 49:  # ord('1')
            if oi >= len_ones or i % X != ones[oi]:
                print("No")
                return
            oi += 1
        else:
            if zi >= len_zeros or i % Y != zeros[zi]:
                print("No")
                return
            zi += 1

    if oi == len_ones and zi == len_zeros:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        if m == 0:
            return n * (n + 1) // 2

        buckets = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, i))

        total = 0
        gains = [0] * m

        top1 = 0          # largest active smaller endpoint
        top2 = 0          # second largest distinct active smaller endpoint
        count_top1 = 0    # number of active pairs with smaller endpoint == top1
        owner = -1        # pair index if count_top1 == 1, else -1

        for r in range(1, n + 1):
            # Activate all pairs whose larger endpoint is r before evaluating r.
            for x, idx in buckets[r]:
                if x > top1:
                    top2 = top1
                    top1 = x
                    count_top1 = 1
                    owner = idx
                elif x == top1:
                    count_top1 += 1
                    owner = -1
                elif x > top2:
                    top2 = x

            # If exactly one active pair attains the maximum threshold,
            # removing it lowers the threshold from top1 to top2.
            if count_top1 == 1 and owner != -1:
                gains[owner] += top1 - top2

            # Valid subarrays ending at r have left endpoint > top1.
            total += r - top1

        return total + max(gains)

import sys


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    adj = [[] for _ in range(n + 1)]
    idx = 2

    for _ in range(m):
        x = int(data[idx])
        y = int(data[idx + 1])
        z = int(data[idx + 2])
        idx += 3

        if x == y:
            if z != 0:
                sys.stdout.write("-1\n")
                return
            continue

        adj[x].append((y, z))
        adj[y].append((x, z))

    del data

    pot = [-1] * (n + 1)
    ans = [0] * (n + 1)

    for start in range(1, n + 1):
        if pot[start] != -1:
            continue

        if not adj[start]:
            pot[start] = 0
            ans[start] = 0
            continue

        pot[start] = 0
        stack = [start]
        comp = []
        vals = []
        max_val = 0

        while stack:
            u = stack.pop()
            comp.append(u)
            pu = pot[u]
            vals.append(pu)

            if pu > max_val:
                max_val = pu

            for v, w in adj[u]:
                np = pu ^ w
                pv = pot[v]

                if pv == -1:
                    pot[v] = np
                    stack.append(v)
                elif pv != np:
                    sys.stdout.write("-1\n")
                    return

        size = len(comp)
        offset = 0

        if max_val:
            for b in range(max_val.bit_length()):
                cnt = 0
                for val in vals:
                    cnt += (val >> b) & 1

                if cnt * 2 > size:
                    offset |= 1 << b

        if offset:
            for u, val in zip(comp, vals):
                ans[u] = val ^ offset
        else:
            for u, val in zip(comp, vals):
                ans[u] = val

    sys.stdout.write(" ".join(map(str, ans[1:])) + "\n")


if __name__ == "__main__":
    solve()

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)

        # Outside the official constraints, but keeps the code safe.
        if m == 0:
            return ""
        if n == 0:
            return "a" * (m - 1)

        L = n + m - 1
        pat = [ord(ch) - 97 for ch in str2]
        is_T = [ch == 'T' for ch in str1]

        # Force every 'T' window to equal str2.
        fixed = [-1] * L
        for i, t in enumerate(is_T):
            if t:
                for j in range(m):
                    p = i + j
                    c = pat[j]
                    old = fixed[p]
                    if old == -1:
                        fixed[p] = c
                    elif old != c:
                        return ""

        # KMP prefix function.
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and pat[i] != pat[j]:
                j = pi[j - 1]
            if pat[i] == pat[j]:
                j += 1
            pi[i] = j

        fallback = pi[m - 1]

        # Automaton states are 0..m. State m means a match just ended.
        # From state m, the next character is processed from fallback.
        trans = [[0] * 26 for _ in range(m + 1)]
        for q in range(m + 1):
            start = fallback if q == m else q
            row = trans[q]
            for c in range(26):
                if c == pat[start]:
                    row[c] = start + 1
                elif start == 0:
                    row[c] = 0
                else:
                    row[c] = trans[pi[start - 1]][c]

        # src[c][t] is a bitmask of states q such that trans[q][c] == t.
        src = [[0] * (m + 1) for _ in range(26)]
        for q in range(m + 1):
            bit = 1 << q
            row = trans[q]
            for c in range(26):
                src[c][row[c]] |= bit

        # Precompute non-empty target/source pairs for fast DP transitions.
        src_lists = []
        for c in range(26):
            lst = []
            row = src[c]
            for t in range(m + 1):
                sm = row[t]
                if sm:
                    lst.append((1 << t, sm))
            src_lists.append(lst)

        # combined[t] is the union over all characters of src[c][t].
        combined = [0] * (m + 1)
        for c in range(26):
            row = src[c]
            for t in range(m + 1):
                combined[t] |= row[t]

        combined_list = []
        for t in range(m + 1):
            sm = combined[t]
            if sm:
                combined_list.append((1 << t, sm))

        state_bits = [1 << q for q in range(m + 1)]
        all_states = (1 << (m + 1)) - 1
        not_m_mask = all_states ^ state_bits[m]

        # forbidden[pos] is true when position pos ends an 'F' window.
        forbidden = [False] * L
        for pos in range(m - 1, L):
            forbidden[pos] = not is_T[pos - m + 1]

        # dp[pos] is a bitmask of automaton states before position pos
        # from which the suffix pos..L-1 can be completed legally.
        dp = [0] * (L + 1)
        dp[L] = all_states

        src_lists_local = src_lists
        combined_list_local = combined_list

        for pos in range(L - 1, -1, -1):
            allowed = dp[pos + 1]

            # A transition into state m means the window ending here equals str2.
            # That is forbidden exactly at 'F' window ends.
            if forbidden[pos]:
                allowed &= not_m_mask

            if not allowed:
                return ""

            fc = fixed[pos]
            mask = 0

            if fc != -1:
                for bit, sm in src_lists_local[fc]:
                    if allowed & bit:
                        mask |= sm
            else:
                for bit, sm in combined_list_local:
                    if allowed & bit:
                        mask |= sm

            if not mask:
                return ""
            dp[pos] = mask

        if not (dp[0] & 1):
            return ""

        # Greedily reconstruct the lexicographically smallest valid string.
        letters = "abcdefghijklmnopqrstuvwxyz"
        res = []
        state = 0

        for pos in range(L):
            fc = fixed[pos]
            forb = forbidden[pos]

            if fc != -1:
                ns = trans[state][fc]
                if ns == m and forb:
                    return ""
                if not (dp[pos + 1] & state_bits[ns]):
                    return ""
                state = ns
                res.append(letters[fc])
            else:
                chosen = -1
                row = trans[state]
                for c in range(26):
                    ns = row[c]
                    if ns == m and forb:
                        continue
                    if dp[pos + 1] & state_bits[ns]:
                        chosen = c
                        break

                if chosen == -1:
                    return ""

                state = row[chosen]
                res.append(letters[chosen])

        return "".join(res)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        if k <= 0:
            return []

        # Any count larger than the initial k is equivalent for unranking.
        limit = k + 1

        # Capped factorials.
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            if fact[i - 1] > limit // i:
                fact[i] = limit
            else:
                v = fact[i - 1] * i
                fact[i] = limit if v > limit else v

        def mul_cap(a: int, b: int) -> int:
            if a >= limit or b >= limit:
                return limit
            if a > limit // b:
                return limit
            return a * b

        def completions(odd_rem: int, even_rem: int, last_parity: int) -> int:
            """
            Count valid suffixes after the last chosen element has parity last_parity.
            Parity convention: 1 = odd, 0 = even.
            """
            length = odd_rem + even_rem
            if length == 0:
                return 1

            start_parity = 1 - last_parity
            need_start = (length + 1) // 2
            need_other = length // 2

            if start_parity == 1:
                if odd_rem != need_start or even_rem != need_other:
                    return 0
            else:
                if even_rem != need_start or odd_rem != need_other:
                    return 0

            return mul_cap(fact[odd_rem], fact[even_rem])

        odd_total = (n + 1) // 2
        even_total = n // 2

        # Total number of valid permutations, capped at limit.
        total = 0
        for x in range(1, n + 1):
            parity = x & 1
            odd_rem = odd_total - (1 if parity == 1 else 0)
            even_rem = even_total - (1 if parity == 0 else 0)
            cnt = completions(odd_rem, even_rem, parity)

            if total >= limit or cnt >= limit or total > limit - cnt:
                total = limit
            else:
                total += cnt

        if total < k:
            return []

        used = [False] * (n + 1)
        odd_rem = odd_total
        even_rem = even_total
        prev_parity = -1
        ans = []

        # Greedy lexicographic unranking.
        for _ in range(n):
            chosen = -1

            for x in range(1, n + 1):
                if used[x]:
                    continue

                parity = x & 1
                if prev_parity != -1 and parity == prev_parity:
                    continue

                next_odd = odd_rem - (1 if parity == 1 else 0)
                next_even = even_rem - (1 if parity == 0 else 0)
                cnt = completions(next_odd, next_even, parity)

                if cnt >= k:
                    chosen = x
                    break

                k -= cnt

            if chosen == -1:
                return []

            used[chosen] = True
            ans.append(chosen)

            if chosen & 1:
                odd_rem -= 1
            else:
                even_rem -= 1

            prev_parity = chosen & 1

        return ans

import sys

MOD = 998244353


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    if len(data) == 2:
        s = data[1][:N]
    else:
        s = b"".join(data[1:])[:N]

    # Bit for pair (x, y), x,y in {0,1}.
    def bit(x, y):
        return 1 << ((x << 1) | y)

    def mask(pairs):
        m = 0
        for x, y in pairs:
            m |= bit(x, y)
        return m

    # Allowed (a_{i-1}, a_i) pairs for each possible d_i.
    # a_i = 1 means cycle edge i -> i+1.
    rel0 = [
        mask([(0, 1)]),                       # d = 0
        mask([(0, 0), (1, 1)]),               # d = 1
        mask([(1, 0)]),                       # d = 2
    ]
    rel1 = [
        mask([(0, 1)]),                       # d = 0
        mask([(0, 1), (0, 0), (1, 1)]),       # d = 1
        mask([(0, 0), (1, 1), (1, 0)]),       # d = 2
        mask([(1, 0)]),                       # d = 3
    ]

    # A relation is stored as a 4-bit mask.
    # Split it into two row subsets:
    #   u = possible current values starting from 0
    #   v = possible current values starting from 1
    # For a local relation, row_table[S] is the set of next values reachable
    # from any current value in subset S.
    def row_table(rel):
        tab = []
        for S in range(4):
            T = 0
            for y in range(2):
                if S & (1 << y):
                    for z in range(2):
                        if rel & bit(y, z):
                            T |= 1 << z
            tab.append(T)
        return tuple(tab)

    tabs0 = [row_table(r) for r in rel0]
    tabs1 = [row_table(r) for r in rel1]

    # Transition matrices on all 16 relation masks.
    # Transitions to the empty relation are omitted because it is dead.
    mat0 = [[0] * 16 for _ in range(16)]
    mat1 = [[0] * 16 for _ in range(16)]

    for cur in range(16):
        u = cur & 3
        v = (cur >> 2) & 3

        for tab in tabs0:
            nxt = tab[u] | (tab[v] << 2)
            if nxt:
                mat0[cur][nxt] += 1

        for tab in tabs1:
            nxt = tab[u] | (tab[v] << 2)
            if nxt:
                mat1[cur][nxt] += 1

    # Keep only states reachable from the identity relation.
    start = 9  # identity: (0,0) and (1,1)
    reachable = [False] * 16
    reachable[start] = True
    stack = [start]

    while stack:
        st = stack.pop()
        for mat in (mat0, mat1):
            row = mat[st]
            for nxt, w in enumerate(row):
                if w and not reachable[nxt]:
                    reachable[nxt] = True
                    stack.append(nxt)

    old_to_new = [-1] * 16
    states = []
    for i in range(16):
        if reachable[i]:
            old_to_new[i] = len(states)
            states.append(i)

    B = len(states)

    rmat0 = [[0] * B for _ in range(B)]
    rmat1 = [[0] * B for _ in range(B)]

    for old in states:
        i = old_to_new[old]

        for nxt, w in enumerate(mat0[old]):
            if w:
                j = old_to_new[nxt]
                if j != -1:
                    rmat0[i][j] += w

        for nxt, w in enumerate(mat1[old]):
            if w:
                j = old_to_new[nxt]
                if j != -1:
                    rmat1[i][j] += w

    start_idx = old_to_new[start]
    accept_idx = [
        old_to_new[st]
        for st in states
        if (st & 1) or (st & 8)  # contains (0,0) or (1,1)
    ]

    # Generate an unrolled transition function for speed.
    def make_expr(mat):
        exprs = []
        for j in range(B):
            terms = []
            for i in range(B):
                w = mat[i][j]
                if w:
                    if w == 1:
                        terms.append(f"v{i}")
                    else:
                        terms.append(f"v{i}*{w}")

            if not terms:
                exprs.append("0")
            elif len(terms) == 1 and "*" not in terms[0]:
                exprs.append(terms[0])
            else:
                exprs.append("(" + " + ".join(terms) + ") % mod")
        return exprs

    expr0 = make_expr(rmat0)
    expr1 = make_expr(rmat1)

    if B == 1:
        unpack = "v0, = dp"
    else:
        unpack = ", ".join(f"v{i}" for i in range(B)) + " = dp"

    lines = [
        "def run(s, dp):",
        f"    mod = {MOD}",
        "    for ch in s:",
        "        " + unpack,
        "        if ch == 49:",
    ]
    for j, e in enumerate(expr1):
        lines.append(f"            dp[{j}] = {e}")
    lines.append("        else:")
    for j, e in enumerate(expr0):
        lines.append(f"            dp[{j}] = {e}")
    lines.append("    return dp")

    code = "\n".join(lines)

    # Generic fallback, normally not used.
    edges0 = []
    edges1 = []
    for i in range(B):
        for j in range(B):
            if rmat0[i][j]:
                edges0.append((i, j, rmat0[i][j]))
            if rmat1[i][j]:
                edges1.append((i, j, rmat1[i][j]))

    try:
        ns = {}
        exec(code, ns)
        run = ns["run"]
    except Exception:
        def run(s, dp, edges0=edges0, edges1=edges1, B=B, mod=MOD):
            for ch in s:
                ndp = [0] * B
                if ch == 49:
                    for f, t, m in edges1:
                        ndp[t] += dp[f] * m
                else:
                    for f, t, m in edges0:
                        ndp[t] += dp[f] * m
                dp = [x % mod for x in ndp]
            return dp

    dp = [0] * B
    dp[start_idx] = 1
    dp = run(s, dp)

    ans = sum(dp[i] for i in accept_idx) % MOD
    print(ans)


if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        C = 4 * side

        # Map each boundary point to its coordinate on the square perimeter.
        # The perimeter is treated as a circle of circumference 4 * side.
        coords = []
        for x, y in points:
            if y == 0:
                t = x
            elif x == side:
                t = side + y
            elif y == side:
                t = 2 * side + (side - x)
            else:
                t = 3 * side + (side - y)
            coords.append(t)

        coords.sort()
        n = len(coords)

        # Duplicated coordinates handle circular wraparound.
        arr = coords + [t + C for t in coords]
        m = 2 * n

        def feasible(d: int) -> bool:
            if d == 0:
                return True

            # nxt[i] = first index j > i with arr[j] - arr[i] >= d.
            nxt = [0] * m
            j = 0
            a = arr
            mm = m
            dd = d

            for i in range(mm):
                if j <= i:
                    j = i + 1
                ai = a[i]
                while j < mm and a[j] - ai < dd:
                    j += 1
                nxt[i] = j

            limit = C - d
            steps = range(k - 1)
            nx = nxt
            aa = a

            # Try every original point as the first selected point in circular order.
            for i in range(n):
                pos = i
                for _ in steps:
                    pos = nx[pos]
                    if pos >= mm:
                        break
                else:
                    # The final wraparound gap back to point i must also be at least d.
                    if aa[pos] <= aa[i] + limit:
                        return True

            return False

        # For k >= 4, the answer cannot exceed side.
        # Also, k points on a circle of circumference C have min gap <= floor(C / k).
        lo = 0
        hi = min(side, C // k)

        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        def kmp_occurrences(text: str, pat: str):
            n = len(text)
            m = len(pat)
            if m == 0:
                return []
            if m > n:
                return []

            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j

            occ = []
            j = 0
            for i, ch in enumerate(text):
                while j > 0 and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                    if j == m:
                        occ.append(i - m + 1)
                        j = pi[j - 1]
            return occ

        parts = p.split('*')
        # The problem guarantees exactly two '*', but padding keeps the code
        # safe for patterns with fewer stars.
        if len(parts) < 3:
            parts += [''] * (3 - len(parts))

        A, B, C = parts[0], parts[1], parts[2]
        n = len(s)

        # Literal blocks cannot overlap, so their total length is a lower bound.
        if len(A) + len(B) + len(C) > n:
            return -1

        cache = {}
        pieces = []

        for part in (A, B, C):
            if part:
                occ = cache.get(part)
                if occ is None:
                    occ = kmp_occurrences(s, part)
                    cache[part] = occ
                if not occ:
                    return -1
                pieces.append((len(part), occ))

        m = len(pieces)

        if m == 0:
            return 0

        if m == 1:
            return pieces[0][0]

        INF = n + 1

        if m == 2:
            l0, occ0 = pieces[0]
            l1, occ1 = pieces[1]

            ans = INF
            i = 0
            last = -1
            len0 = len(occ0)
            min_possible = l0 + l1

            for start1 in occ1:
                while i < len0 and occ0[i] + l0 <= start1:
                    last = occ0[i]
                    i += 1

                if last != -1:
                    length = start1 + l1 - last
                    if length < ans:
                        ans = length
                        if ans == min_possible:
                            break

            return -1 if ans == INF else ans

        l0, occ0 = pieces[0]
        l1, occ1 = pieces[1]
        l2, occ2 = pieces[2]

        ans = INF
        i = 0
        last0 = -1
        j = 0
        len0 = len(occ0)
        len2 = len(occ2)
        min_possible = l0 + l1 + l2

        for start1 in occ1:
            while i < len0 and occ0[i] + l0 <= start1:
                last0 = occ0[i]
                i += 1

            end1 = start1 + l1
            while j < len2 and occ2[j] < end1:
                j += 1

            # Since B ends are nondecreasing, once no C remains, future B
            # occurrences cannot have a valid C either.
            if j == len2:
                break

            if last0 != -1:
                length = occ2[j] + l2 - last0
                if length < ans:
                    ans = length
                    if ans == min_possible:
                        break

        return -1 if ans == INF else ans

