from typing import List
from bisect import bisect_left

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        def insert_index(t, x):
            if not t:
                return (x,)
            if len(t) == 1:
                if x < t[0]:
                    return (x, t[0])
                return (t[0], x)
            if len(t) == 2:
                if x < t[0]:
                    return (x, t[0], t[1])
                if x < t[1]:
                    return (t[0], x, t[1])
                return (t[0], t[1], x)
            if x < t[0]:
                return (x, t[0], t[1], t[2])
            if x < t[1]:
                return (t[0], x, t[1], t[2])
            if x < t[2]:
                return (t[0], t[1], x, t[2])
            return (t[0], t[1], t[2], x)

        n = len(intervals)
        arr = [(r, l, w, i) for i, (l, r, w) in enumerate(intervals)]
        arr.sort()
        ends = [item[0] for item in arr]

        dp = [[None] * 5 for _ in range(n + 1)]
        dp[0][0] = (0, ())

        for i, (r, l, w, idx) in enumerate(arr, 1):
            p = bisect_left(ends, l, 0, i - 1)
            prev_row = dp[i - 1]
            cur_row = dp[i]
            cur_row[0] = prev_row[0]
            compat_row = dp[p]

            for j in range(1, 5):
                best = prev_row[j]
                prev = compat_row[j - 1]

                if prev is not None:
                    cand_score = prev[0] + w

                    if best is None or cand_score > best[0]:
                        best = (cand_score, insert_index(prev[1], idx))
                    elif cand_score == best[0]:
                        nt = insert_index(prev[1], idx)
                        if nt < best[1]:
                            best = (cand_score, nt)

                cur_row[j] = best

        best = None
        for j in range(5):
            state = dp[n][j]
            if state is None:
                continue
            if (
                best is None
                or state[0] > best[0]
                or (state[0] == best[0] and state[1] < best[1])
            ):
                best = state

        return list(best[1]) if best is not None else []

import sys
from collections import deque

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    a = [x - 1 for x in data[2:2 + n]]

    indeg = [0] * n
    for p in a:
        indeg[p] += 1

    q = deque([i for i, d in enumerate(indeg) if d == 0])
    dp = [None] * n

    mod = MOD
    rng = range(m)
    base = [i % mod for i in range(1, m + 1)]

    while q:
        u = q.popleft()

        arr = dp[u]
        if arr is None:
            # Leaf: original dp is all 1, so its prefix contribution is 1,2,...,M.
            arr = base.copy()
        else:
            # Convert original dp values into prefix sums in-place.
            s = 0
            for i in rng:
                s += arr[i]
                if s >= mod:
                    s -= mod
                arr[i] = s

        p = a[u]
        par = dp[p]
        if par is None:
            dp[p] = arr
        else:
            for i in rng:
                par[i] = (par[i] * arr[i]) % mod

        dp[u] = None
        indeg[p] -= 1
        if indeg[p] == 0:
            q.append(p)

    visited = [False] * n
    ans = 1

    for i in range(n):
        if indeg[i] > 0 and not visited[i]:
            cycle = []
            cur = i
            while not visited[cur]:
                visited[cur] = True
                cycle.append(cur)
                cur = a[cur]

            prod = None
            for u in cycle:
                arr = dp[u]
                if arr is not None:
                    if prod is None:
                        prod = arr.copy()
                    else:
                        for j in rng:
                            prod[j] = (prod[j] * arr[j]) % mod
                    dp[u] = None

            if prod is None:
                total = m % mod
            else:
                total = sum(prod) % mod

            ans = (ans * total) % mod

    print(ans)

