        got = sol.minLength(s, numOps)
        if got != expected:
            all_pass = False
            print(f"FAIL: s={s!r}, numOps={numOps}, expected={expected}, got={got}")

    if all_pass:
        print("SAMPLE TESTS PASS")
    else:
        print("SAMPLE TESTS FAIL")
